      function persist(){try{localStorage.setItem(viewKey,JSON.stringify({expanded:state.expanded,...Object.fromEntries(Object.entries(views).map(([kind,value])=>[kind,{q:value.q,stars:[...value.stars],elements:[...value.elements],type:value.type}]))}));}catch{}}
